/**
 * WebGCS Connection Manager Module
 * Handles MAVLink connection management and heartbeat monitoring
 */

window.ConnectionManager = (function() {
    'use strict';

    // Private variables
    let heartbeatCount = 0;
    let lastHeartbeatTime = 0;
    let heartbeatInterval = null;
    let isConnecting = false;

    // DOM elements
    let elements = {};

    /**
     * Initialize Connection Manager
     */
    function initialize() {
        console.log('Initializing Connection Manager...');

        // Cache DOM elements
        cacheElements();

        // Setup event listeners
        setupEventListeners();

        // Initialize UI state
        updateConnectionUI(false);

        console.log('Connection Manager initialized');
    }

    /**
     * Cache DOM Elements
     */
    function cacheElements() {
        elements = {
            connectionStatus: document.getElementById('connection-status'),
            heartbeatIndicator: document.getElementById('heartbeat-indicator'),
            heartbeatCounter: document.getElementById('heartbeat-counter'),
            heartbeatSound: document.getElementById('heartbeat-sound'),
            ipAddress: document.getElementById('ip-address'),
            portNumber: document.getElementById('port-number'),
            connectBtn: document.getElementById('connect-btn'),
            disconnectBtn: document.getElementById('disconnect-btn')
        };

        // Check for missing elements
        Object.entries(elements).forEach(([key, element]) => {
            if (!element) {
                console.warn(`Connection Manager: Element '${key}' not found`);
            }
        });
    }

    /**
     * Setup Event Listeners
     */
    function setupEventListeners() {
        // Connect button
        if (elements.connectBtn) {
            elements.connectBtn.addEventListener('click', handleConnect);
        }

        // Disconnect button
        if (elements.disconnectBtn) {
            elements.disconnectBtn.addEventListener('click', handleDisconnect);
        }

        // Input validation
        if (elements.portNumber) {
            elements.portNumber.addEventListener('input', validatePortInput);
        }

        if (elements.ipAddress) {
            elements.ipAddress.addEventListener('input', validateIpInput);
        }

        // Heartbeat sound toggle
        if (elements.heartbeatSound) {
            elements.heartbeatSound.addEventListener('change', handleHeartbeatSoundToggle);
        }

        // Listen for global events
        if (window.WebGCS && window.WebGCS.eventBus) {
            window.WebGCS.eventBus.addEventListener('telemetry_updated', handleTelemetryUpdate);
            window.WebGCS.eventBus.addEventListener('websocket_connected', handleWebSocketConnect);
            window.WebGCS.eventBus.addEventListener('websocket_disconnected', handleWebSocketDisconnect);
            window.WebGCS.eventBus.addEventListener('connection_status', handleConnectionStatusUpdate);
        }
    }

    /**
     * Handle Connect Button Click
     */
    function handleConnect() {
        if (isConnecting) return;

        const ip = elements.ipAddress?.value?.trim() || '192.168.193.235';
        const port = parseInt(elements.portNumber?.value) || 5678;

        // Validate inputs
        if (!validateIP(ip)) {
            window.WebGCS?.showMessage('Invalid IP address format', 'error');
            return;
        }

        if (port < 1 || port > 65535) {
            window.WebGCS?.showMessage('Port must be between 1 and 65535', 'error');
            return;
        }

        console.log(`Attempting to connect to ${ip}:${port}`);

        // Update UI to connecting state
        setConnectingState(true);

        // Send connection command via SocketIO
        if (window.WebGCS?.socket) {
            window.WebGCS.socket.emit('connect_drone', {
                ip: ip,
                port: port
            });

            console.log(`Connection request sent to ${ip}:${port}`);
            window.WebGCS?.showMessage(`Connecting to ${ip}:${port}...`, 'info');

            // Set timeout for connection attempt
            setTimeout(() => {
                if (isConnecting && !window.WebGCS.droneConnected) {
                    setConnectingState(false);
                    window.WebGCS.showMessage('Connection timeout', 'warning');
                }
            }, 30000); // 30 second timeout

        } else {
            setConnectingState(false);
            window.WebGCS?.showMessage('WebGCS not ready', 'error');
        }
    }

    /**
     * Handle Disconnect Button Click
     */
    function handleDisconnect() {
        console.log('Disconnecting from drone...');

        // Send disconnect command
        if (window.WebGCS?.sendCommand) {
            window.WebGCS.sendCommand('disconnect');
            window.WebGCS.showMessage('Disconnecting...', 'info');
        }

        // Reset heartbeat
        resetHeartbeat();

        // Update UI
        updateConnectionUI(false);
    }

    /**
     * Set Connecting State
     */
    function setConnectingState(connecting) {
        isConnecting = connecting;

        if (elements.connectBtn) {
            elements.connectBtn.disabled = connecting;
            elements.connectBtn.textContent = connecting ? 'Connecting...' : 'Connect';
        }

        if (elements.disconnectBtn) {
            elements.disconnectBtn.disabled = !connecting && !window.WebGCS?.droneConnected;
        }

        // Update status
        if (elements.connectionStatus && connecting) {
            elements.connectionStatus.className = 'status-indicator connecting';
            elements.connectionStatus.textContent = 'Connecting to drone...';
        }
    }

    /**
     * Update Connection UI
     */
    function updateConnectionUI(connected, systemId = 0) {
        if (elements.connectionStatus) {
            if (connected) {
                elements.connectionStatus.className = 'status-indicator connected';
                elements.connectionStatus.textContent = systemId > 0 
                    ? `Connected to drone (System ${systemId})`
                    : 'Connected to drone';
            } else {
                elements.connectionStatus.className = 'status-indicator disconnected';
                elements.connectionStatus.textContent = 'Disconnected from drone';
            }
        }

        if (elements.connectBtn) {
            elements.connectBtn.disabled = connected || isConnecting;
        }

        if (elements.disconnectBtn) {
            elements.disconnectBtn.disabled = !connected;
        }

        isConnecting = false;
    }

    /**
     * Handle Heartbeat Update
     */
    function updateHeartbeat() {
        heartbeatCount++;
        lastHeartbeatTime = Date.now();

        // Update counter
        if (elements.heartbeatCounter) {
            elements.heartbeatCounter.textContent = heartbeatCount;
        }

        // Animate heartbeat icon
        if (elements.heartbeatIndicator) {
            elements.heartbeatIndicator.classList.add('pulse');
            setTimeout(() => {
                elements.heartbeatIndicator.classList.remove('pulse');
            }, 300);
        }

        // Play heartbeat sound if enabled
        if (elements.heartbeatSound?.checked) {
            playHeartbeatSound();
        }

        // Notify audio manager for voice announcements
        if (window.WebGCS?.modules?.AudioManager?.onHeartbeat) {
            window.WebGCS.modules.AudioManager.onHeartbeat();
        }
    }

    /**
     * Reset Heartbeat
     */
    function resetHeartbeat() {
        heartbeatCount = 0;
        lastHeartbeatTime = 0;

        if (elements.heartbeatCounter) {
            elements.heartbeatCounter.textContent = '0';
        }

        if (heartbeatInterval) {
            clearInterval(heartbeatInterval);
            heartbeatInterval = null;
        }
    }

    /**
     * Play Heartbeat Sound
     */
    function playHeartbeatSound() {
        try {
            // Create audio context if not exists
            if (!window.audioContext) {
                window.audioContext = new (window.AudioContext || window.webkitAudioContext)();
            }

            // Create beep sound
            const oscillator = window.audioContext.createOscillator();
            const gainNode = window.audioContext.createGain();

            oscillator.connect(gainNode);
            gainNode.connect(window.audioContext.destination);

            oscillator.frequency.setValueAtTime(800, window.audioContext.currentTime);
            gainNode.gain.setValueAtTime(0, window.audioContext.currentTime);
            gainNode.gain.linearRampToValueAtTime(0.1, window.audioContext.currentTime + 0.01);
            gainNode.gain.exponentialRampToValueAtTime(0.001, window.audioContext.currentTime + 0.1);

            oscillator.start(window.audioContext.currentTime);
            oscillator.stop(window.audioContext.currentTime + 0.1);

        } catch (error) {
            console.warn('Could not play heartbeat sound:', error);
        }
    }

    /**
     * Validate IP Address
     */
    function validateIP(ip) {
        const ipRegex = /^(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/;
        return ipRegex.test(ip);
    }

    /**
     * Validate Port Input
     */
    function validatePortInput(event) {
        const port = parseInt(event.target.value);
        if (isNaN(port) || port < 1 || port > 65535) {
            event.target.setCustomValidity('Port must be between 1 and 65535');
        } else {
            event.target.setCustomValidity('');
        }
    }

    /**
     * Validate IP Input
     */
    function validateIpInput(event) {
        const ip = event.target.value.trim();
        if (ip && !validateIP(ip)) {
            event.target.setCustomValidity('Invalid IP address format');
        } else {
            event.target.setCustomValidity('');
        }
    }

    /**
     * Handle Heartbeat Sound Toggle
     */
    function handleHeartbeatSoundToggle(event) {
        const enabled = event.target.checked;
        console.log('Heartbeat sound:', enabled ? 'enabled' : 'disabled');

        // Store preference
        localStorage.setItem('webgcs_heartbeat_sound', enabled.toString());

        if (enabled && window.audioContext?.state === 'suspended') {
            window.audioContext.resume();
        }
    }

    /**
     * Event Handlers
     */
    function handleTelemetryUpdate(event) {
        const data = event.detail;

        // Check for heartbeat (new data received)
        if (data.connected) {
            updateHeartbeat();
        }

        // Update connection status
        updateConnectionUI(data.connected, data.system_id);
    }

    function handleWebSocketConnect() {
        // WebSocket connected - enable connect button if not already connected
        if (elements.connectBtn && !window.WebGCS?.droneConnected) {
            elements.connectBtn.disabled = false;
        }
    }

    function handleWebSocketDisconnect() {
        // WebSocket disconnected - reset everything
        updateConnectionUI(false);
        resetHeartbeat();
        setConnectingState(false);
    }

    /**
     * Handle Connection Status Updates from Server
     */
    function handleConnectionStatusUpdate(event) {
        const status = event.detail;
        console.log('Received connection status:', status);

        // Update connection state based on status
        switch (status.status) {
            case 'connecting':
                setConnectingState(true);
                break;

            case 'connected':
                setConnectingState(false);
                updateConnectionUI(true, status.system_id || 0);
                break;

            case 'disconnected':
                setConnectingState(false);
                updateConnectionUI(false);
                resetHeartbeat();
                break;

            case 'error':
                setConnectingState(false);
                updateConnectionUI(false);
                break;

            default:
                console.warn('Unknown connection status:', status.status);
        }
    }

    /**
     * Public API
     */
    return {
        initialize: initialize,

        // Connection state methods
        isConnected: () => window.WebGCS?.droneConnected || false,
        isConnecting: () => isConnecting,
        getHeartbeatCount: () => heartbeatCount,
        getLastHeartbeatTime: () => lastHeartbeatTime,

        // Module lifecycle callbacks
        onTelemetryUpdate: handleTelemetryUpdate,
        onConnectionChange: (data) => {
            updateConnectionUI(data.connected);
        },
        onResize: () => {
            // Handle responsive layout changes if needed
        }
    };
})();

// Load saved preferences
document.addEventListener('DOMContentLoaded', function() {
    // Restore heartbeat sound preference
    const heartbeatSoundSaved = localStorage.getItem('webgcs_heartbeat_sound');
    if (heartbeatSoundSaved !== null) {
        const checkbox = document.getElementById('heartbeat-sound');
        if (checkbox) {
            checkbox.checked = heartbeatSoundSaved === 'true';
        }
    }
});

/**
 * WebGCS Main Application Module
 * Coordinates all modules and manages global application state
 */

// Global Application State
window.WebGCS = {
    socket: null,
    isConnected: false,
    droneConnected: false,
    modules: {},
    telemetryData: {
        connected: false,
        armed: false,
        mode: 'UNKNOWN',
        lat: 0.0,
        lon: 0.0,
        alt_rel: 0.0,
        alt_abs: 0.0,
        heading: 0.0,
        vx: 0.0,
        vy: 0.0,
        vz: 0.0,
        system_id: 0,
        component_id: 0,
        system_status: 0,
        battery_voltage: 0.0,
        current: 0.0,
        gps_fix_type: 0,
        satellites_visible: 0,
        hdop: 99.9
    },
    eventBus: new EventTarget()
};

/**
 * Initialize WebGCS Application
 */
function initializeWebGCS() {
    console.log('Initializing WebGCS v2.0...');

    // Initialize SocketIO connection
    initializeSocket();

    // Initialize all modules
    initializeModules();

    // Setup global event listeners
    setupGlobalEvents();

    // Setup confirmation dialog
    setupConfirmationDialog();

    console.log('WebGCS initialization complete');
}

/**
 * Initialize SocketIO Connection
 */
function initializeSocket() {
    try {
        WebGCS.socket = io();

        WebGCS.socket.on('connect', handleSocketConnect);
        WebGCS.socket.on('disconnect', handleSocketDisconnect);
        WebGCS.socket.on('connect_error', handleSocketError);
        WebGCS.socket.on('telemetry_update', handleTelemetryUpdate);
        WebGCS.socket.on('command_result', handleCommandResult);
        WebGCS.socket.on('connection_status', handleConnectionStatus);

        console.log('SocketIO initialized');
    } catch (error) {
        console.error('SocketIO initialization failed:', error);
        showMessage('SocketIO connection failed', 'error');
    }
}

/**
 * Initialize All Application Modules
 */
function initializeModules() {
    const modules = [
        'ConnectionManager',
        'TelemetryDisplay', 
        'FlightControls',
        'NavigationControls',
        'MapController',
        'OfflineMaps',
        'AudioManager',
        'MessageLogger'
    ];

    modules.forEach(moduleName => {
        try {
            if (window[moduleName] && typeof window[moduleName].initialize === 'function') {
                window[moduleName].initialize();
                WebGCS.modules[moduleName] = window[moduleName];
                console.log(`${moduleName} initialized`);
            }
        } catch (error) {
            console.error(`Failed to initialize ${moduleName}:`, error);
        }
    });
}

/**
 * Setup Global Event Listeners
 */
function setupGlobalEvents() {
    // Listen for module events
    WebGCS.eventBus.addEventListener('telemetry_updated', (event) => {
        // Broadcast telemetry updates to all modules
        Object.values(WebGCS.modules).forEach(module => {
            if (module.onTelemetryUpdate) {
                module.onTelemetryUpdate(event.detail);
            }
        });
    });

    WebGCS.eventBus.addEventListener('connection_changed', (event) => {
        // Broadcast connection status changes
        Object.values(WebGCS.modules).forEach(module => {
            if (module.onConnectionChange) {
                module.onConnectionChange(event.detail);
            }
        });
    });

    // Handle keyboard shortcuts
    document.addEventListener('keydown', handleKeyboardShortcuts);

    // Handle window resize for responsive layout
    window.addEventListener('resize', handleWindowResize);
}

/**
 * Setup Confirmation Dialog
 */
function setupConfirmationDialog() {
    const dialog = document.getElementById('confirmation-dialog');
    const yesBtn = document.getElementById('confirm-yes');
    const noBtn = document.getElementById('confirm-no');

    if (!dialog || !yesBtn || !noBtn) return;

    yesBtn.addEventListener('click', () => {
        dialog.classList.remove('active');
        if (window.confirmationCallback) {
            window.confirmationCallback(true);
            window.confirmationCallback = null;
        }
    });

    noBtn.addEventListener('click', () => {
        dialog.classList.remove('active');
        if (window.confirmationCallback) {
            window.confirmationCallback(false);
            window.confirmationCallback = null;
        }
    });

    // Close on outside click
    dialog.addEventListener('click', (e) => {
        if (e.target === dialog) {
            dialog.classList.remove('active');
            if (window.confirmationCallback) {
                window.confirmationCallback(false);
                window.confirmationCallback = null;
            }
        }
    });
}

/**
 * Socket Event Handlers
 */
function handleSocketConnect() {
    console.log('Connected to WebGCS server');
    WebGCS.isConnected = true;

    // Update WebSocket status
    const statusElement = document.getElementById('websocket-status');
    if (statusElement) {
        statusElement.textContent = 'WebSocket: Connected';
        statusElement.className = 'websocket-status ws-connected';
    }

    // Notify modules
    WebGCS.eventBus.dispatchEvent(new CustomEvent('websocket_connected'));
    showMessage('Connected to WebGCS server', 'info');
}

function handleSocketDisconnect() {
    console.log('Disconnected from WebGCS server');
    WebGCS.isConnected = false;
    WebGCS.droneConnected = false;

    // Update WebSocket status
    const statusElement = document.getElementById('websocket-status');
    if (statusElement) {
        statusElement.textContent = 'WebSocket: Disconnected';
        statusElement.className = 'websocket-status ws-disconnected';
    }

    // Notify modules
    WebGCS.eventBus.dispatchEvent(new CustomEvent('websocket_disconnected'));
    showMessage('Disconnected from WebGCS server', 'warning');
}

function handleSocketError(error) {
    console.error('Socket connection error:', error);

    const statusElement = document.getElementById('websocket-status');
    if (statusElement) {
        statusElement.textContent = 'WebSocket: Error';
        statusElement.className = 'websocket-status ws-disconnected';
    }

    showMessage('WebSocket connection error', 'error');
}

function handleTelemetryUpdate(data) {
    // Update global telemetry state
    Object.assign(WebGCS.telemetryData, data);

    // Check for connection status change
    const wasConnected = WebGCS.droneConnected;
    WebGCS.droneConnected = data.connected;

    if (wasConnected !== WebGCS.droneConnected) {
        WebGCS.eventBus.dispatchEvent(new CustomEvent('connection_changed', {
            detail: { connected: WebGCS.droneConnected }
        }));
    }

    // Broadcast telemetry update
    WebGCS.eventBus.dispatchEvent(new CustomEvent('telemetry_updated', {
        detail: data
    }));
}

function handleCommandResult(result) {
    console.log('Command result:', result);

    // Show result message
    const message = result.success 
        ? `Command ${result.command} succeeded`
        : `Command ${result.command} failed: ${result.error}`;
    const type = result.success ? 'info' : 'error';

    showMessage(message, type);

    // Notify modules
    WebGCS.eventBus.dispatchEvent(new CustomEvent('command_result', {
        detail: result
    }));
}

function handleConnectionStatus(status) {
    console.log('Connection status:', status);

    // Show status message
    const message = status.message || `Connection ${status.status}`;
    const type = status.status === 'connected' ? 'success' : 
                 status.status === 'error' ? 'error' : 'info';

    showMessage(message, type);

    // Notify connection manager module
    WebGCS.eventBus.dispatchEvent(new CustomEvent('connection_status', {
        detail: status
    }));
}

/**
 * Handle Keyboard Shortcuts
 */
function handleKeyboardShortcuts(event) {
    // Only handle shortcuts if not typing in input
    if (event.target.tagName === 'INPUT' || event.target.tagName === 'TEXTAREA') {
        return;
    }

    // Ctrl/Cmd + shortcuts
    if (event.ctrlKey || event.metaKey) {
        switch (event.key.toLowerCase()) {
            case 'c':
                event.preventDefault();
                if (WebGCS.modules.MapController && WebGCS.modules.MapController.centerMap) {
                    WebGCS.modules.MapController.centerMap();
                }
                break;
            case 'm':
                event.preventDefault();
                toggleOfflineMapsPanel();
                break;
        }
    }

    // Function key shortcuts
    switch (event.key) {
        case 'F1':
            event.preventDefault();
            showMessage('Keyboard shortcuts: Ctrl+C (Center Map), Ctrl+M (Toggle Offline Maps)', 'info');
            break;
        case 'Escape':
            event.preventDefault();
            // Close any open modals/panels
            const modal = document.querySelector('.modal.active');
            if (modal) {
                modal.classList.remove('active');
            }
            const panel = document.querySelector('.offline-maps-panel.active');
            if (panel) {
                panel.classList.remove('active');
            }
            break;
    }
}

/**
 * Handle Window Resize
 */
function handleWindowResize() {
    // Notify modules about resize
    Object.values(WebGCS.modules).forEach(module => {
        if (module.onResize) {
            module.onResize();
        }
    });
}

/**
 * Global Utility Functions
 */

/**
 * Show confirmation dialog
 */
function showConfirmation(title, message, callback) {
    const dialog = document.getElementById('confirmation-dialog');
    const titleElement = document.getElementById('confirm-title');
    const messageElement = document.getElementById('confirm-message');

    if (!dialog || !titleElement || !messageElement) return;

    titleElement.textContent = title;
    messageElement.textContent = message;
    dialog.classList.add('active');

    window.confirmationCallback = callback;
}

/**
 * Show status message
 */
function showMessage(message, type = 'info') {
    if (WebGCS.modules.MessageLogger && WebGCS.modules.MessageLogger.addMessage) {
        WebGCS.modules.MessageLogger.addMessage(message, type);
    } else {
        console.log(`[${type.toUpperCase()}] ${message}`);
    }
}

/**
 * Send command to server
 */
function sendCommand(command, params = {}) {
    if (!WebGCS.socket || !WebGCS.isConnected) {
        showMessage('Not connected to server', 'error');
        return false;
    }

    console.log('Sending command:', command, params);

    WebGCS.socket.emit('flight_command', {
        command: command,
        params: params,
        timestamp: Date.now()
    });

    return true;
}

/**
 * Toggle offline maps panel
 */
function toggleOfflineMapsPanel() {
    const panel = document.getElementById('offline-maps-panel');
    if (panel) {
        panel.classList.toggle('active');
    }
}

/**
 * Format coordinate for display
 */
function formatCoordinate(value, decimals = 6) {
    return parseFloat(value).toFixed(decimals);
}

/**
 * Format altitude for display
 */
function formatAltitude(value, unit = 'm') {
    return `${parseFloat(value).toFixed(1)} ${unit}`;
}

/**
 * Format heading for display
 */
function formatHeading(value) {
    return `${parseFloat(value).toFixed(1)}°`;
}

/**
 * Format voltage for display
 */
function formatVoltage(value) {
    return `${parseFloat(value).toFixed(1)} V`;
}

/**
 * Format current for display
 */
function formatCurrent(value) {
    return `${parseFloat(value).toFixed(1)} A`;
}

// Expose global functions
window.WebGCS.showConfirmation = showConfirmation;
window.WebGCS.showMessage = showMessage;
window.WebGCS.sendCommand = sendCommand;
window.WebGCS.formatCoordinate = formatCoordinate;
window.WebGCS.formatAltitude = formatAltitude;
window.WebGCS.formatHeading = formatHeading;
window.WebGCS.formatVoltage = formatVoltage;
window.WebGCS.formatCurrent = formatCurrent;

// Initialize when DOM is ready
document.addEventListener('DOMContentLoaded', initializeWebGCS);

